function switchPill(x, y, w, name, lab) {
  var on = P[name].v > 0.5;
  rect(x, y, w, 12, on ? C.amber : C.panel, true);
  rect(x, y, w, 12, on ? C.amber : C.line, false);
  textC(lab, x + w / 2, y + 9, 7.5, on ? C.bg : C.mid, true);
  if (locked[name]) padlock(x - 8, y + 4, C.pink);
  hit({ x: x, y: y, w: w, h: 12, kind: "switch", name: name });
}

// logo: STØMP, the Ø is a kick drum seen from the front (a ring with a beater mark), it thumps on a hit
function drawLogo(x, y) {
  var age = hitT > 0 ? (now() - hitT) / 1000 : 9, k = Math.exp(-age * 9);
  text("ST", x, y, 17, C.ink, true);
  var ox = x + tw("ST", 17, true) + 9, r = 6.6 * (1 + 0.18 * k);
  circle(ox, y - 6, r, C.ink, false, 2.2);
  circle(ox, y - 6, r * 0.42, C.accent, true, 1, 0.35 + 0.65 * k);
  line(ox - r * 1.05, y - 6 + r * 1.05, ox + r * 1.05, y - 6 - r * 1.05, C.ink, 2.2);
  text("MP", ox + 9, y, 17, C.ink, true);
}

function paintLeft() {
  var L = 10, LW = LEFT_W - 14, cx = L + LW / 2;
  drawLogo(12, 27);
  // preset: < NAME >
  rect(L, 36, LW, 18, C.panel, true); rect(L, 36, LW, 18, C.line, false);
  textC("<", L + 8, 48.5, 9, C.mid, true); textC(">", L + LW - 8, 48.5, 9, C.mid, true);
  textC(presetName, cx, 48.5, 8.5, curSlot >= 0 ? C.accent : C.ink, true);
  hit({ x: L, y: 36, w: 18, h: 18, kind: "preset", name: "prev", d: -1 });
  hit({ x: L + LW - 18, y: 36, w: 18, h: 18, kind: "preset", name: "next", d: 1 });
  // PLAY pad: flashes with every hit (MIDI or the pad)
  var age = hitT > 0 ? (now() - hitT) / 1000 : 9, fl = Math.exp(-age * 7);
  rect(L, 60, LW, 40, C.panel, true);
  rect(L, 60, LW, 40, C.accent, true, 1, 0.12 + 0.75 * fl * (0.4 + 0.6 * lastVel));
  rect(L, 60, LW, 40, C.line, false);
  textC("PLAY", cx, 78, 10, fl > 0.4 ? C.bg : C.ink, true);
  textC(noteName(lastNote) + "  " + fmtHz(fnote(lastNote)), cx, 92, 8, fl > 0.4 ? C.bg : C.mid, true);
  hit({ x: L, y: 60, w: LW, h: 40, kind: "play", name: "play" });
  button(L, 106, 38, 20, "DICE", false, "dice", "dice");
  button(L + 41, 106, 30, 20, "UNDO", false, "undo", "undo", 7.5);
  if (!undoStack.length) rect(L + 41, 106, 30, 20, C.bg, true, 1, 0.55);
  // SAVE: arms, then a slot is the target (blinking)
  var blink = saveArmed && Math.floor(now() / 250) % 2 === 0;
  rect(L + 74, 106, LW - 74, 20, saveArmed ? C.pink : C.panel, true);
  rect(L + 74, 106, LW - 74, 20, saveArmed ? C.pink : C.line, false);
  textC("SAVE", L + 74 + (LW - 74) / 2, 119.3, 7.5, saveArmed ? C.bg : C.ink, true);
  hit({ x: L + 74, y: 106, w: LW - 74, h: 20, kind: "save", name: "save" });
  // 8 user slots: 2 rows of 4
  for (var i = 0; i < 8; i++) {
    var sx = L + (i % 4) * 26, sy = 132 + Math.floor(i / 4) * 16, full = !!slotData[i], cur = curSlot === i;
    rect(sx, sy, 24, 13, cur ? C.accent : full ? [0.22, 0.22, 0.22, 1] : C.bg, true);
    rect(sx, sy, 24, 13, saveArmed ? (blink ? C.pink : C.line) : full ? C.mid : C.line, false);
    textC(String(i + 1), sx + 12, sy + 9.5, 7.5, cur ? C.bg : full ? C.ink : C.dim, true);
    hit({ x: sx, y: sy, w: 24, h: 13, kind: "slot", name: "slot" + i, slot: i });
  }
}

function paintCol(c) {
  rect(c.x, 6, c.w, 157, C.panel, true);
  var cx = c.x + c.w / 2;
  if (c.sw) {   // title on the left, the switch on the right
    text(c.t, c.x + 8, 19, 9, C.ink, true);
    switchPill(c.x + c.w - 34, 10, 28, c.sw, c.sw === "p808" ? "808" : "PRE");
  } else textC(c.t, cx, 19, 9, C.ink, true);
  // big knob
  knob(cx, 52, 17, c.big);
  textC(label(c.big), cx, 84, 7.5, C.mid, true);
  valueOrDepth(c.big, cx, 96, 8.5);
  // small knobs
  var n = c.sm.length;
  for (var i = 0; i < n; i++) {
    var sx = n === 1 ? cx : n === 2 ? c.x + c.w * (i ? 0.73 : 0.27) : n === 3 ? c.x + c.w * (0.18 + 0.32 * i) : c.x + c.w * (0.14 + 0.24 * i);
    var nm = c.sm[i], off = nm === "pit_crv" && P.p808.v > 0.5;   // 808 mode: the pitch follows the loudness, no CURVE
    textC(label(nm), sx, 116, 7, off ? C.dim : C.mid, true);
    knob(sx, 133, n >= 3 ? 9.5 : 10.5, nm, off || (nm === "nz_lrt" && P.nz_lfo.v <= 0));   // RATE grey while LFO is 0
    valueOrDepth(nm, sx, 157, 7.5);
    if (nm === "nz_lfo") {   // the LFO is alive: where it is right now (from the engine)
      var on = P.nz_lfo.v > 0;   // a short track under the label, the dot swings left - right
      line(sx - 9, 120, sx + 9, 120, C.line, 1.2);
      circle(sx + lfoNow * 9, 120, 2, on ? C.accent : C.dim, true);
    }
  }
}

// the display: the LAST HIT as it sounded (velocity, note and random included) — or the knobs before the
// first hit. Waveform (body + sub, drive), body envelope (cyan), sub envelope (green), pitch (pink).
var waveCache = { key: "" };
function waveKey(E) { var s = lastNote + ":"; for (var k in E) s += E[k] + ","; return s; }
function computeWave() {
  var E = effAll(), key = waveKey(E); if (key === waveCache.key) return waveCache;
  var aatt = M.aatt(E.amp_att), tmax = Math.max(0.08, (Math.max(M.alen(E.amp_len), E.sub_lvl > 0 ? M.alen(E.sub_len) : 0) + aatt) * 1.08);
  var sr = 6000, n = Math.ceil(tmax * sr), cols = [], wpx = DW - 16, ph = 0, pm = 0, i;
  var fmr = M.fmr(E.fm_rat), fi = 6 * E.fm_amt * E.fm_amt, fd = M.fdec(E.fm_dec), phs = E.amp_phs * 0.25;
  var dg = pw2(E.dr_amt * 5), dtg = tanh(dg), dm = Math.min(1, (E.dr_amt + E.dr_asym) * 5), pre = E.dr_pre > 0.5;
  for (i = 0; i < wpx; i++) cols.push([0, 0]);
  for (i = 0; i < n; i++) {
    var t = i / sr, m = model(t, lastNote, E);
    var b = Math.sin(2 * Math.PI * (ph + phs) + fi * Math.exp(-t / fd) * Math.sin(2 * Math.PI * pm)), so = Math.sin(2 * Math.PI * (ph + phs));
    ph += Math.min(m.f, 2900) / sr; pm += Math.min(m.f * fmr, 2900) / sr;
    var y = pre ? shp(b, dg, dtg, E.dr_knee, E.dr_asym, dm) * m.env + shp(so, dg, dtg, E.dr_knee, E.dr_asym, dm) * m.senv
      : shp(b * m.env + so * m.senv, dg, dtg, E.dr_knee, E.dr_asym, dm);
    var cc = Math.min(wpx - 1, Math.floor(t / tmax * wpx));
    if (y < cols[cc][0]) cols[cc][0] = y; if (y > cols[cc][1]) cols[cc][1] = y;
  }
  var mx = 1; for (i = 0; i < wpx; i++) mx = Math.max(mx, -cols[i][0], cols[i][1]);   // body + sub can pass 1: fit
  for (i = 0; i < wpx; i++) { cols[i][0] /= mx; cols[i][1] /= mx; }
  waveCache = { key: key, cols: cols, tmax: tmax, E: E, scale: 1 / mx, f0: model(0, lastNote, E).f, f1: fnote(lastNote, E.tune) };
  return waveCache;
}
function curve(w, x0, wpx, fn, c) {
  var steps = 100, i, px, py;
  col(c); mgraphics.set_line_width(1.5);
  for (i = 0; i <= steps; i++) {
    px = x0 + i / steps * wpx; py = fn(i / steps * w.tmax);
    if (i === 0) mgraphics.move_to(px, py); else mgraphics.line_to(px, py);
  }
  mgraphics.stroke();
}
function paintDisplay() {
  rect(DX, DY, DW, DH, C.screen, true);
  rect(DX, DY, DW, DH, C.line, false);
  if (patchMode) { paintPatchHelp(); return; }
  var w = computeWave(), x0 = DX + 8, wpx = DW - 16, top = DY + 24, h = DH - 50, mid = top + h / 2, i;
  line(x0, mid, x0 + wpx, mid, C.line, 1, 0.6);
  for (i = 0; i < w.cols.length; i++) line(x0 + i + 0.5, mid - w.cols[i][1] * h / 2, x0 + i + 0.5, mid - w.cols[i][0] * h / 2 + 0.01, C.mid, 1, 0.7);
  var lf0 = Math.log(w.f0), lf1 = Math.log(w.f1);
  curve(w, x0, wpx, function (t) { return mid - model(t, lastNote, w.E).env * w.scale * h / 2; }, C.accent);
  if (w.E.sub_lvl > 0) curve(w, x0, wpx, function (t) { return mid - model(t, lastNote, w.E).senv * w.scale * h / 2; }, C.green);
  curve(w, x0, wpx, function (t) { var f = model(t, lastNote, w.E).f; return top + h - (lf0 > lf1 + 0.000001 ? (Math.log(f) - lf1) / (lf0 - lf1) : 0) * h; }, C.pink);
  // top: where it starts, how long; bottom: what was played, where it lands (big)
  text(fmtHz(w.f0), x0, DY + 15, 8.5, C.pink, true);
  textR(fmtMs(w.tmax / 1.08), DX + DW - 8, DY + 15, 8.5, C.mid, true);
  textC(hitN > 0 ? "LAST HIT  vel " + Math.round(lastVel * 127) : "KNOBS", DX + DW / 2, DY + 15, 7.5, hitN > 0 ? C.ink : C.dim, true);
  paintTuner(w);
  if (hitT > 0) {   // playhead
    var age = (now() - hitT) / 1000;
    if (age < w.tmax) { var px = x0 + age / w.tmax * wpx; line(px, top - 4, px, top + h + 4, C.pink, 1.2, 0.9); }
  }
}
// TUNER (bottom of the screen): the note the last hit really rings at (engine out 5: its oscillator, every
// modulation and the 808 drift included), how many cents off, a needle; a click on the scale = SNAP: TUNE moves
// so the next hit lands exactly on the nearest note. Before the first hit: the knobs' landing pitch (dim).
var tunerHz = 0;
function tuner(hz) { hz = +hz; if (hz > 0 && Math.abs(hz - tunerHz) > 0.0001) { tunerHz = hz; dirty = true; } }
function tunerRead(w) {
  var hz = tunerHz > 0 && hitN > 0 ? tunerHz : w.f1, m = 69 + 12 * Math.log(hz / 440) / Math.LN2, n = Math.round(m);
  return { hz: hz, note: n, cents: Math.round((m - n) * 100), real: tunerHz > 0 && hitN > 0 };
}
var TUN_W = 64;
function paintTuner(w) {
  var t = tunerRead(w), y = DY + DH - 8, cx = DX + DW / 2, ok = Math.abs(t.cents) <= 5;
  var cc = !t.real ? C.dim : ok ? C.green : C.amber;
  text(noteName(t.note), DX + 8, y, 11, t.real ? C.ink : C.mid, true);
  text((t.cents > 0 ? "+" : "") + t.cents + "c", DX + 8 + tw(noteName(t.note), 11, true) + 4, y, 8.5, cc, true);
  // the scale: -50 .. +50 cents, the needle; a click = SNAP
  var sx0 = cx - TUN_W / 2 + 6, sy = y - 4;
  line(sx0, sy, sx0 + TUN_W, sy, C.line, 1.5);
  line(sx0 + TUN_W / 2, sy - 5, sx0 + TUN_W / 2, sy + 3, C.mid, 1);
  line(sx0, sy - 3, sx0, sy + 2, C.line, 1); line(sx0 + TUN_W, sy - 3, sx0 + TUN_W, sy + 2, C.line, 1);
  var nx = sx0 + TUN_W / 2 + Math.max(-1, Math.min(1, t.cents / 50)) * TUN_W / 2;
  line(nx, sy - 6, nx, sy + 4, cc, 2.5);
  if (hover === "snap" && t.real) textC("SNAP", sx0 + TUN_W / 2, sy - 8, 7, C.ink, true);
  hit({ x: sx0 - 4, y: sy - 12, w: TUN_W + 8, h: 18, kind: "snap", name: "snap" });
  textR(fmtHz(t.hz), DX + DW - 8, y, 10, C.pink, true);
}
// SNAP: TUNE so the measured pitch lands on the nearest note (fine steps: the knob is 48 st wide)
function snap() {
  if (!(tunerHz > 0 && hitN > 0)) return;
  var m = 69 + 12 * Math.log(tunerHz / 440) / Math.LN2, dst = Math.round(m) - m;   // semitones to the nearest note
  var v = Math.max(0, Math.min(1, P.tune.v + dst / 48));
  send("tune", Math.round(v * 100000) / 100000);
  tunerHz = tunerHz * Math.pow(2, dst / 12); dirty = true;
}
function paintPatchHelp() {
  var x = DX + 9, y = DY + 17, s = SRC[selSrc];
  text("PATCH  -  " + s.lab, x, y, 9, s.col, true);
  var L = ["VEL / NOTE / RND on the right = source",
    "click a knob = wire it",
    "drag up / down on it = depth (+ / -)",
    "double-click a knob = cut the cable",
    "VEL: soft notes move the knob",
    "NOTE: higher notes move it (C1 = 0)",
    "RND: every hit lands somewhere new",
    "click here or PATCH = back"];
  for (var i = 0; i < L.length; i++) text(L[i], x, y + 15 + i * 12.5, 7.5, C.ink, false);
  button(DX + DW - 66, DY + DH - 20, 58, 15, "CLEAR " + s.short, false, "clear", "clear", 7);
  hit({ x: DX, y: DY, w: DW, h: DH - 24, kind: "void", name: "void" });
}

function srcY(s) { return 20 + s * 31; }
function paintSources() {
  rect(SX - 4, 6, 68, 157, C.panel, true);
  for (var s = 0; s < SRC.length; s++) {
    var y = srcY(s), src = SRC[s], sel = patchMode && selSrc === s;
    circle(SX + 6, y - 3, 5, src.col, true);
    if (sel) circle(SX + 6, y - 3, 8, src.col, false, 1.2);
    text(src.short, SX + 15, y, 8.5, C.ink, true);
    hit({ x: SX - 2, y: y - 12, w: 60, h: 14, kind: "src", name: "src" + s, src: s });
    var n = src.amt;   // global amount: drag
    textC(pct(P[n].v), SX + 26, y + 13, 8.5, src.col, true);
    hit({ x: SX - 2, y: y + 3, w: 60, h: 13, kind: "amount", name: n });
    if (hover === n || (drag && drag.name === n)) rect(SX - 2, y + 3, 60, 13, src.col, false, 1, 0.5);
  }
  button(SX, 106, 56, 18, "PATCH", patchMode, "patch", "patch");
  // output meter (two bars)
  var db = function (v) { var d = 20 * Math.log(Math.max(v, 0.000001)) / Math.LN10; return Math.max(0, Math.min(1, (d + 48) / 48)); };
  var ls = [levL, levR];
  for (var c = 0; c < 2; c++) {
    var my = 136 + c * 6, f = db(ls[c]);
    rect(SX, my, 56, 3, C.line, true);
    rect(SX, my, 56 * f, 3, ls[c] > 0.98 ? C.pink : C.accent, true);
  }
  text("OUT", SX, 158, 7, C.mid, true);
}

// cables (patch mode): every source to every knob it reaches; the selected source bright
function cable(x1, y1, x2, y2, c, a) {
  col(c, a); mgraphics.set_line_width(1.8);
  var sag = 18 + Math.abs(x2 - x1) * 0.12;
  mgraphics.move_to(x1, y1); mgraphics.curve_to(x1 - 30, Math.min(y1 + sag, H0 - 6), x2 + 20, Math.min(y2 + sag, H0 - 6), x2, y2); mgraphics.stroke();   // stays inside the panel
}
function paintCables() {
  if (!patchMode) return;
  for (var k = 0; k <= SRC.length; k++) {
    var si = k < SRC.length ? k : selSrc;            // the selected one last (on top)
    if (k < SRC.length && si === selSrc) continue;
    var src = SRC[si], sy = srcY(si) - 3, a = si === selSrc ? 0.8 : 0.2;
    for (var n in KNOB_POS) {
      if (depthOf(n, si) === 0) continue;
      var kp = KNOB_POS[n];
      cable(SX + 6, sy, kp[0], kp[1] + kp[2] * 0.5, src.col, a);
      circle(kp[0], kp[1] + kp[2] * 0.5, 2.5, src.col, true, 1, a + 0.2);
    }
  }
}

function paint() {
  var sz = mgraphics.size;
  scaleF = Math.min(sz[0] / W0, sz[1] / H0); if (!(scaleF > 0)) scaleF = 1;
  mgraphics.scale(scaleF, scaleF);
  hits = []; KNOB_POS = {};
  rect(0, 0, W0, H0, C.bg, true);
  if (patchMode) hit({ x: 0, y: 0, w: W0, h: H0, kind: "void", name: "void" });   // click outside = back
  // each part on its own: an error in one part must not leave the rest of the panel blank
  safe(paintLeft);
  for (var i = 0; i < COLS.length; i++) safe(paintCol, COLS[i]);
  safe(paintDisplay);
  safe(paintSources);
  safe(paintCables);
}
var reported = {};
var lastError = "";
function safe(fn, arg) {
  try { fn(arg); } catch (e) {
    var msg = "STOMP panel: " + (fn.name || "part") + ": " + e;
    if (!reported[msg]) { reported[msg] = 1; if (typeof post === "function") post(msg + "\n"); }
    lastError = msg;
  }
}

// ---------- mouse ----------
function find(x, y) { for (var i = hits.length - 1; i >= 0; i--) { var h = hits[i]; if (x >= h.x && x <= h.x + h.w && y >= h.y && y <= h.y + h.h) return h; } return null; }
// Max: onclick(x, y, button, cmd, shift, capslock, option, ctrl)
function onclick(x, y, but, cmd, shift, caps, alt) {
  x /= scaleF; y /= scaleF;
  var h = find(x, y); if (!h) return;
  if (h.kind !== "save" && h.kind !== "slot") saveArmed = false;
  if (alt && (h.kind === "knob" || h.kind === "switch") && !patchMode) { locked[h.name] = !locked[h.name]; dirty = true; return; }
  if (h.kind === "knob") {
    if (patchMode) {
      var dn = SRC[selSrc].pre + h.name;
      if (P[dn].v === 0) send(dn, 0.5);
      drag = { kind: "depth", name: dn, y0: y, n0: P[dn].v === 0 ? 0.5 : P[dn].v };
    } else drag = { kind: "knob", name: h.name, y0: y, n0: P[h.name].v };
  }
  else if (h.kind === "switch") send(h.name, P[h.name].v > 0.5 ? 0 : 1);
  else if (h.kind === "amount") drag = { kind: "knob", name: h.name, y0: y, n0: P[h.name].v };
  else if (h.kind === "src") { if (patchMode && selSrc === h.src) patchMode = false; else { selSrc = h.src; patchMode = true; } }
  else if (h.kind === "patch") patchMode = !patchMode;
  else if (h.kind === "void") patchMode = false;
  else if (h.kind === "clear") { for (var i = 0; i < SPEC_KNOBS.length; i++) send(SRC[selSrc].pre + SPEC_KNOBS[i].n, 0); }
  else if (h.kind === "play") play();
  else if (h.kind === "dice") dice();
  else if (h.kind === "undo") undo();
  else if (h.kind === "preset") loadPreset(preset + h.d);
  else if (h.kind === "save") saveArmed = !saveArmed;
  else if (h.kind === "snap") snap();
  else if (h.kind === "slot") { if (alt) clearSlot(h.slot); else if (saveArmed) saveSlot(h.slot); else loadSlot(h.slot); }
  dirty = true;
}
function ondrag(x, y, but, cmd, shift) {
  if (!drag) return;
  x /= scaleF; y /= scaleF;
  var k = shift ? 0.0007 : 0.007;
  if (drag.kind === "knob") send(drag.name, Math.round(Math.max(0, Math.min(1, drag.n0 + (drag.y0 - y) * k)) * 1000) / 1000);
  if (drag.kind === "depth") send(drag.name, Math.round(Math.max(-1, Math.min(1, drag.n0 + (drag.y0 - y) * k * 2)) * 1000) / 1000);
  if (!but) { drag = null; dirty = true; }
}
function ondblclick(x, y) {
  x /= scaleF; y /= scaleF;
  var h = find(x, y); if (!h) return;
  if (h.kind === "knob") { if (patchMode) send(SRC[selSrc].pre + h.name, 0); else send(h.name, P[h.name].d); }
  if (h.kind === "amount") send(h.name, P[h.name].d);
  drag = null;
}
function onidle(x, y) { var h = find(x / scaleF, y / scaleF), k = h ? h.name : null; if (k !== hover) { hover = k; dirty = true; } }
function onidleout() { if (hover) { hover = null; dirty = true; } }
function onresize() { dirty = true; }
